def deflate(input: String, level: Int) -> String
    {
        val bytes = input.getBytes("UTF-8")
        val compressedSize = deflateCompressed(bytes, level)
        return compressedSize.toString()
    }

    def deflateCompressed(input: String, level: Int): Int = {
        val compressedData = new Array[Byte](input.length)
        for (var i = 0; i < input.length; i++) {
            compressedData[i] = input.charCodeAt(i)
        }
        val compressedBytes = new Array[Byte](compressedData.length)
        for (var j = 0; j < compressedData.length; j++) {
            compressedBytes[j] = (int)compressedData[j]
        }
        val compressedSize = compress(compressedBytes, level)
        return compressedSize
    }
}

