// Example usage
    public static void main(String[] args) {
        com.worldql.client.WorldQLClient worldqlClient = new com.worldql.client.WorldQLClient();

        // Create a heartbeat message
        Instruction heartbeat = Instruction.Heartbeat(HeartbeatMessage.HEARTBEAT);
        worldqlClient.send(heartbeat);

        // Read a heartbeat message
        com.worldql.client.Message heartbeatMessage = worldqlClient.receive(HeartbeatMessage.MESSAGE_TYPE);
        System.out.println("Received heartbeat message: " + heartbeatMessage);

        // Update a record
        Instruction recordCreate = Instruction.RecordCreate(RecordCreateMessage.RECORD_CREATE);
        worldqlClient.send(recordCreate);

        // Read a record created by a heartbeat
        com.worldql.client.Message recordCreated = worldqlClient.receive(recordCreate);

        // Delete a record
        Instruction recordDelete = Instruction.RecordDelete(RecordDeleteMessage.RECORD_DELETE);
        worldqlClient.send(recordDelete);

        // Reply to a message
        Instruction reply = Instruction.RecordReply(RecordReplyMessage.REPLY);
        worldqlClient.send(reply);

        // Unknown message
        Instruction unknown = Instruction.Unknown();
        worldqlClient.send(unknown);

        // Close the connection
        worldqlClient.close();

